      val ctxEpoch = reader.u8(s"$path.ctx_epoch").toInt
      ckRange(ctxEpoch.toLong, 0, 255, s"$path.ctx_epoch")
      val requestSeq = reader.u16(s"$path.request_seq").toInt
      ckRange(requestSeq.toLong, 0, 65535, s"$path.request_seq")
      val logicalAm = reader.u8(s"$path.logical_am").toInt
      ckRange(logicalAm.toLong, 0, 1, s"$path.logical_am")
      val bundleSlots = reader.u8(s"$path.bundle_slots").toInt
      ckRange(bundleSlots.toLong, 1, 2, s"$path.bundle_slots")
      val outputRows = reader.u16(s"$path.output_rows").toInt
      ckRange(outputRows.toLong, 0, 65535, s"$path.output_rows")
      val outputCols = reader.u16(s"$path.output_cols").toInt
      ckRange(outputCols.toLong, 0, 65535, s"$path.output_cols")
      val accFormat = reader.u8(s"$path.acc_format")
      ckEnum(accFormat, AccFormatValid, s"$path.acc_format")
      val layout = reader.u8(s"$path.layout")
      ckEnum(layout, LayoutValid, s"$path.layout")
      val outputL1Slot = reader.u16(s"$path.output_l1_slot").toInt
      ckRange(outputL1Slot.toLong, 0, 65535, s"$path.output_l1_slot")
      val outputDtype = reader.u8(s"$path.output_dtype")
      ckEnum(outputDtype, DtypeValid, s"$path.output_dtype")
      val byteCount = reader.u32(s"$path.byte_count")
      ckRange(byteCount.toLong, 0L, 262144L, s"$path.byte_count")
      val chainConfig = EpilogueConfig.decodePayload(reader, s"$path.chain_config")
      if (byteCount.toLong != outputRows.toLong * outputCols.toLong * 4)
        throw ProtocolError(s"$path.byte_count", "must equal output_rows * output_cols")
      if (chainConfig.nCols != outputCols)
        throw ProtocolError(s"$path.chain_config.n_cols", "must equal output_cols")
      val isI8 = outputDtype == DtypeI8
      val hasQuant = chainConfig.quantPresent
      if (isI8 != hasQuant)
        throw ProtocolError(s"$path.output_dtype", "i8 output requires exactly the quant parameters")
      new AmRequest(
        tileId = tileId,
        ctxId = ctxId,
        ctxEpoch = ctxEpoch,
        requestSeq = requestSeq,
        logicalAm = logicalAm,
        bundleSlots = bundleSlots,
        outputRows = outputRows,
        outputCols = outputCols,
        accFormat = accFormat,
        layout = layout,
        outputL1Slot = outputL1Slot,
        outputDtype = outputDtype,
        byteCount = byteCount,
        chainConfig = chainConfig,
      )
    }
  }

