  final case class SubmitStep(
      leaseHandle: Int,
      seq: Int,
      mode: Int,
      finalFlag: Boolean,
      transpose: Int,
      a: OperandView,
      b: OperandView,
      kExtent: Int,
      inputReadyTokens: Vector[EventToken],
      inputUsageHandles: Vector[AllocationRef],
      kMask: Vector[Int],
      completionEvent: EventToken
  ) extends BoaMessage {
    def encodePayload(writer: Writer): Unit = {
      writer.u16(leaseHandle)
      writer.u16(seq)
      writer.u8(mode)
      writer.u8(if (finalFlag) 1 else 0)
      writer.u8(transpose)
      a.encodePayload(writer)
      b.encodePayload(writer)
      writer.u16(kExtent)
      writer.u8(inputReadyTokens.length)
      inputReadyTokens.foreach(item => item.encodePayload(writer))
      writer.u8(inputUsageHandles.length)
      inputUsageHandles.foreach(item => item.encodePayload(writer))
      writer.u16(kMask.length)
      kMask.foreach(item => writer.u8(item))
      completionEvent.encodePayload(writer)
    }
  }
  private object SubmitStep {
    def decodePayload(reader: Reader, path: String): SubmitStep = {
      val leaseHandle = reader.u16(s"$path.lease_handle").toInt
      ckRange(leaseHandle.toLong, 0, 65535, s"$path.lease_handle")
      val seq = reader.u16(s"$path.seq").toInt
      ckRange(seq.toLong, 0, 65535, s"$path.seq")
      val mode = reader.u8(s"$path.mode")
      ckEnum(mode, StepModeValid, s"$path.mode")
      val finalFlagRaw = reader.u8(s"$path.final")
      ckWireBool(finalFlagRaw, s"$path.final")
      val finalFlag = finalFlagRaw == 1
      val transpose = reader.u8(s"$path.transpose")
      ckEnum(transpose, TransposeValid, s"$path.transpose")
      val a = OperandView.decodePayload(reader, s"$path.a")
      val b = OperandView.decodePayload(reader, s"$path.b")
      val kExtent = reader.u16(s"$path.k_extent").toInt
      ckRange(kExtent.toLong, 0, 65535, s"$path.k_extent")
      val inputReadyTokensCount = reader.u8(s"$path.input_ready_tokens.count")
      val inputReadyTokens = (0 until inputReadyTokensCount).map(_ => EventToken.decodePayload(reader, s"$path.input_ready_tokens[]")).toVector
      val inputUsageHandlesCount = reader.u8(s"$path.input_usage_handles.count")
      val inputUsageHandles = (0 until inputUsageHandlesCount).map(_ => AllocationRef.decodePayload(reader, s"$path.input_usage_handles[]")).toVector
      val kMaskCount = reader.u16(s"$path.k_mask.count")
      val kMask = (0 until kMaskCount).map(_ => reader.u8(s"$path.k_mask[]").toInt).toVector
      kMask.zipWithIndex.foreach { case (item, index) => ckRange(item.toLong, 0, 1, s"$path.k_mask[$index]") }
      val completionEvent = EventToken.decodePayload(reader, s"$path.completion_event")
      if (inputReadyTokens.exists(item =>
        item.ctxId == completionEvent.ctxId &&
        item.ctxEpoch == completionEvent.ctxEpoch &&
        item.eventId == completionEvent.eventId))
        throw ProtocolError(s"$path.input_ready_tokens", "a step must not wait on its own completion event")
      new SubmitStep(
        leaseHandle = leaseHandle,
        seq = seq,
        mode = mode,
        finalFlag = finalFlag,
        transpose = transpose,
        a = a,
        b = b,
        kExtent = kExtent,
        inputReadyTokens = inputReadyTokens,
        inputUsageHandles = inputUsageHandles,
        kMask = kMask,
        completionEvent = completionEvent,
      )
    }
  }

