  val messageKinds: Map[String, Int] = Map(
    "AM_REQUEST" -> 1,
    "AM_GRANTED" -> 2,
    "AM_PARKED" -> 3,
    "AM_ERROR" -> 4,
    "AM_WAKE" -> 5,
    "AM_CANCEL" -> 6,
    "SUBMIT_STEP" -> 7,
    "STEP_ACCEPTED" -> 8,
    "STEP_FULL" -> 9,
    "STEP_ERROR" -> 10,
    "EVT_STATUS" -> 11,
    "EVT_TAKE" -> 12,
    "REC_REAP" -> 13,
    "CTX_CANCEL" -> 14,
    "MEM_REQ" -> 15,
    "MEM_RESP" -> 16,
  )

  val kindNames: Map[Int, String] = messageKinds.map { case (k, v) => (v, k) }

  def messageName(message: BoaMessage): String = message match {
    case _: AmCancel => "AM_CANCEL"
    case _: AmError => "AM_ERROR"
    case _: AmGranted => "AM_GRANTED"
    case _: AmParked => "AM_PARKED"
    case _: AmRequest => "AM_REQUEST"
    case _: AmWake => "AM_WAKE"
    case _: CtxCancel => "CTX_CANCEL"
    case _: EvtStatus => "EVT_STATUS"
    case _: EvtTake => "EVT_TAKE"
    case _: MemReq => "MEM_REQ"
    case _: MemResp => "MEM_RESP"
    case _: RecReap => "REC_REAP"
    case _: StepAccepted => "STEP_ACCEPTED"
    case _: StepError => "STEP_ERROR"
    case _: StepFull => "STEP_FULL"
    case _: SubmitStep => "SUBMIT_STEP"
  }

  def encode(message: BoaMessage): Array[Byte] = {
    val writer = new Writer
    message.encodePayload(writer)
    frame(messageKinds(messageName(message)), writer.toBytes)
  }

  def encodeMany(messages: Seq[BoaMessage]): Array[Byte] =
    messages.foldLeft(Array.emptyByteArray)((acc, m) => acc ++ encode(m))

  def decodeStream(data: Array[Byte]): Vector[BoaMessage] = {
    val out = scala.collection.mutable.ArrayBuffer.empty[BoaMessage]
    var pos = 0
    while (pos < data.length) {
      if (data.length - pos < FrameHeaderBytes + 1)
        throw ProtocolError("frame", "truncated frame header")
      if ((data(pos) & 0xff) != Magic0 || (data(pos + 1) & 0xff) != Magic1)
        throw ProtocolError("frame.magic", "bad magic")
      val version = data(pos + 2) & 0xff
      if (version != WireVersion)
        throw ProtocolError("frame.version", s"unknown wire version $version")
      val kind = data(pos + 3) & 0xff
      val length = (data(pos + 4) & 0xff) | ((data(pos + 5) & 0xff) << 8)
      val payloadStart = pos + FrameHeaderBytes + 1
      val payloadEnd = payloadStart + length
      if (payloadEnd > data.length)
        throw ProtocolError("frame.length", "truncated payload")
      val reader = new Reader(data, payloadStart, payloadEnd)
      val message = decodePayload(kind, reader)
      if (reader.pos != payloadEnd)
        throw ProtocolError("frame.length", "payload has trailing bytes")
      out += message
      pos = payloadEnd
    }
    out.toVector
  }

  def reencode(data: Array[Byte]): Array[Byte] = encodeMany(decodeStream(data))

  private def frame(kind: Int, payload: Array[Byte]): Array[Byte] = {
    val out = new Array[Byte](FrameHeaderBytes + 1 + payload.length)
    out(0) = Magic0.toByte
    out(1) = Magic1.toByte
    out(2) = WireVersion.toByte
    out(3) = kind.toByte
    out(4) = (payload.length & 0xff).toByte
    out(5) = ((payload.length >> 8) & 0xff).toByte
    System.arraycopy(payload, 0, out, 6, payload.length)
    out
  }

  private def decodePayload(kind: Int, reader: Reader): BoaMessage = kind match {
    case 1 => AmRequest.decodePayload(reader, "AM_REQUEST")
    case 2 => AmGranted.decodePayload(reader, "AM_GRANTED")
    case 3 => AmParked.decodePayload(reader, "AM_PARKED")
    case 4 => AmError.decodePayload(reader, "AM_ERROR")
    case 5 => AmWake.decodePayload(reader, "AM_WAKE")
    case 6 => AmCancel.decodePayload(reader, "AM_CANCEL")
    case 7 => SubmitStep.decodePayload(reader, "SUBMIT_STEP")
    case 8 => StepAccepted.decodePayload(reader, "STEP_ACCEPTED")
    case 9 => StepFull.decodePayload(reader, "STEP_FULL")
    case 10 => StepError.decodePayload(reader, "STEP_ERROR")
    case 11 => EvtStatus.decodePayload(reader, "EVT_STATUS")
    case 12 => EvtTake.decodePayload(reader, "EVT_TAKE")
    case 13 => RecReap.decodePayload(reader, "REC_REAP")
    case 14 => CtxCancel.decodePayload(reader, "CTX_CANCEL")
    case 15 => MemReq.decodePayload(reader, "MEM_REQ")
    case 16 => MemResp.decodePayload(reader, "MEM_RESP")
    case other => throw ProtocolError("frame.kind", s"unknown message kind $other")
  }
}
